INSERT INTO public.countries (slug, flag, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, documents_en, eligibility_en, timeline_en, sort_order, published) VALUES
('slovenia', '🇸🇮', 'Slovenia', 'سلوفينيا', 'EU work permits in tourism and industry', 'تصاريح عمل أوروبية في السياحة والصناعة', 'An EU member with growing demand for workers in tourism, logistics and manufacturing, and straightforward single-permit procedures.', 'دولة عضو في الاتحاد الأوروبي بطلب متزايد على العمالة في السياحة واللوجستيات والتصنيع، بإجراءات تصريح موحدة وواضحة.', ARRAY['Valid passport (12+ months)','Recent passport photo','CV in English','Medical certificate','Police clearance'], ARRAY['Age 18–45','Basic English','Clean criminal record'], '[{"step":"Application review","time":"3–5 days"},{"step":"Employer matching","time":"2–4 weeks"},{"step":"Single permit","time":"4–8 weeks"},{"step":"Visa & travel","time":"2–3 weeks"}]'::jsonb, 6, true),
('ireland', '🇮🇪', 'Ireland', 'أيرلندا', 'English-speaking careers in Europe''s tech hub', 'مسارات مهنية بالإنجليزية في مركز التقنية الأوروبي', 'Critical skills and general employment permits in one of Europe''s strongest job markets, with English as the working language.', 'تصاريح عمل للمهارات المطلوبة والوظائف العامة في واحدة من أقوى أسواق العمل في أوروبا، والإنجليزية هي لغة العمل.', ARRAY['Valid passport (12+ months)','Recent passport photo','CV in English','Medical certificate','Police clearance','Diplomas & certificates'], ARRAY['Age 21–50','Good English (IELTS 5+ preferred)','Relevant work experience'], '[{"step":"Profile assessment","time":"1 week"},{"step":"Job offer","time":"3–6 weeks"},{"step":"Permit processing","time":"6–10 weeks"},{"step":"Visa & travel","time":"3–4 weeks"}]'::jsonb, 7, true);
